                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            public void HandleCommand(EJMessage msg)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                public async Task<NetworkMessage> HandleCommandAsync(NetworkMessage command,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Logger.Info($"Executing command: {command.Command} from {command.DeviceId}", "RemoteCommand");
    
    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Variant from:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CommandType.CMD_RESTART => await HandleRestartAsync(command, cancellationToken),
    
    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CommandType.CMD_SCREENSHOT => await HandleScreenshotAsync(command, cancellationToken),
    
    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CommandType.CMD_TIMESYNC => await HandleTimeSyncAsync(command, cancellationToken),
    
    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CommandType.CMD_CHGPWD => await HandlePasswordChangeAsync(command, cancellationToken),
    
    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CommandType.CMD_GHOSTREMOTE => await HandleGhostRemoteAsync(command, cancellationToken),
    
    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                CommandType.CMD_GETLOG => await HandleGetLogAsync(command, cancellationToken),
    
    
