                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        case "ALLOWUNSIGNEDLEGACYCOMMANDS":
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (bool.TryParse(pair.Value, out var allowUnsignedLegacyCommands))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
