        public IReadOnlyList<RemoteCommand> GetCommandHistory(int max = 200)
        {
            lock (_sync)
            {
                return _history.Values
                .OrderByDescending(item => item.CreatedAtUtc)
                .Take(Math.Max(1, max))
                .ToArray();
            }
