        private void ExecuteGhostStart(string cmdId, int quality)
        {
            if (_ghostActive)
            {
                SendResult(cmdId, false, "Ghost already active");
                return;
            }
    
        _ghostActive = true;
        _ghostEngine = new GhostRemoteEngine(quality);
        _ghostEngine.OnFrameCaptured += (s, jpg) =>
        {
            // إرسال Frame للسيرفر
            var frame = CommunicationProtocol.BuildGhostFrame(jpg);
            _network.SendMessage(frame);
            OnGhostFrameSent?.Invoke(this, jpg);
        };
        _ghostEngine.Start();
        SendResult(cmdId, true, $"Ghost View started [q={quality}%]");
        AppLogger.Instance.Info($"👁️ Ghost View started (quality={quality}%)", "GhostView");
        }
    
        private void ExecuteGhostStop(string cmdId)
        {
            if (!_ghostActive)
            {
                SendResult(cmdId, false, "Ghost not active");
                return;
            }
        _ghostEngine?.Stop();
        _ghostEngine = null;
        _ghostActive = false;
        SendResult(cmdId, true, "Ghost View stopped");
        AppLogger.Instance.Info("👁️ Ghost View stopped", "GhostView");
        }
    
        private void ExecuteSendFile(string cmdId, string fileName)
        {
            try
            {
                var config = AppConfig.Load();
                var path   = Path.Combine(config.SourcePath, fileName);
                if (!File.Exists(path))
                {
                    SendResult(cmdId, false, $"File not found: {fileName}");
                    return;
                }
    
            var data     = SecurityHelper.ReadFileSafe(path);
            var checksum = SecurityHelper.MD5Hash(data);
            var ok       = _network.SendJournalFile(fileName, data, 0, checksum);
            SendResult(cmdId, ok, ok ? $"File sent [{data.Length / 1024} KB]" : "Send failed");
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteForceSync(string cmdId)
        {
            SendResult(cmdId, true, "Force sync initiated");
            AppLogger.Instance.Info("♻️ Force sync by remote command", "RemoteCmd");
            // يتم التعامل مع الطابور من JournalProcessor
        }
    
        private void SendResult(string cmdId, bool success, string result)
        {
            var frame = CommunicationProtocol.BuildCommandResult(cmdId, success, result);
            _network?.SendMessage(frame);
            AppLogger.Instance.Info($"→ CMD Result [{cmdId}]: {(success ? "✓" : "✗")} {result}", "RemoteCmd");
        }
    
        public void ProcessCommand(string command, string parameters)
        {
            Log("Received command: " + command);
    
            switch (command.ToUpper())
            {
                case "RESTART":
                HandleRestart();
                break;
                case "SCREENSHOT":
                HandleScreenshot();
                break;
                case "TIMESYNC":
                HandleTimeSync(parameters);
                break;
                case "UPDATE_CONFIG":
                HandleConfigUpdate(parameters);
                break;
                case "SHUTDOWN":
                HandleShutdown();
                break;
                default:
                Log("Unknown command: " + command);
                break;
            }
        }
    
        private void HandleRestart()
        {
            Log("Executing restart command...");
            try
            {
                Process.Start("shutdown", "/r /t 30 /c \"EJLive scheduled restart\"");
                Log("System will restart in 30 seconds.");
            }
        catch (Exception ex)
        {
            Log("Restart failed: " + ex.Message);
        }
        }
    
        private void HandleScreenshot()
        {
            Log("Capturing screenshot...");
            try
            {
                Rectangle bounds = Screen.PrimaryScreen.Bounds;
                using (Bitmap bmp = new Bitmap(bounds.Width, bounds.Height))
                {
                    using (Graphics g = Graphics.FromImage(bmp))
                    {
                        g.CopyFromScreen(Point.Empty, Point.Empty, bounds.Size);
                    }
    
                string path = Path.Combine(Path.GetTempPath(), "ejlive_screenshot_" + DateTime.Now.ToString("yyyyMMddHHmmss") + ".png");
                bmp.Save(path, ImageFormat.Png);
                Log("Screenshot saved: " + path);
            }
        }
        catch (Exception ex)
        {
            Log("Screenshot failed: " + ex.Message);
        }
        }
    
        private void HandleTimeSync(string serverTime)
        {
            Log("Syncing time with server: " + serverTime);
            try
            {
                // Parse server time and set local time
                DateTime dt = DateTime.ParseExact(serverTime, "yyyyMMddHHmmss", null);
                string dateCmd = dt.ToString("MM-dd-yyyy");
                string timeCmd = dt.ToString("HH:mm:ss");
    
                Process.Start("cmd", "/c date " + dateCmd);
                Process.Start("cmd", "/c time " + timeCmd);
                Log("Time synchronized successfully.");
            }
        catch (Exception ex)
        {
            Log("Time sync failed: " + ex.Message);
        }
        }
    
        private void HandleConfigUpdate(string configData)
        {
            Log("Updating configuration...");
            try
            {
                string configPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "ejlive.config");
                File.WriteAllText(configPath, configData);
                Log("Configuration updated. Restart required.");
            }
        catch (Exception ex)
        {
            Log("Config update failed: " + ex.Message);
        }
        }
    
        private void HandleShutdown()
        {
            Log("Executing shutdown command...");
            try
            {
                Process.Start("shutdown", "/s /t 60 /c \"EJLive scheduled shutdown\"");
                Log("System will shutdown in 60 seconds.");
            }
        catch (Exception ex)
        {
            Log("Shutdown failed: " + ex.Message);
        }
        }
    
        private void Log(string message)
        {
            OnLogMessage?.Invoke(message);
        }
    
