        /// <summary>
        /// معالج الأوامر البعيدة الكامل — Remote Command Handler
        /// ينفّذ الأوامر الواردة من السيرفر: Restart | Shutdown | ChangePassword
        ///     | Screenshot | Ghost Start | Ghost Stop | SendFile | GetFile | ForceSync
        /// يطبق: D-04 (تسجيل كل عملية في AuditLog)
        /// </summary>
        public class RemoteCommandHandler
        {
            private readonly string _atmId;
            private readonly NetworkManager _network;
            private readonly Action _forceSyncAction;
            private GhostRemoteEngine _ghostEngine;
            private volatile bool _ghostActive;
            private readonly Dictionary<string, RemoteCommand> _commands =
            new Dictionary<string, RemoteCommand>(StringComparer.OrdinalIgnoreCase);
    
            public event EventHandler<RemoteCommand> OnCommandReceived;
            public event EventHandler<RemoteCommand> OnCommandExecuted;
            public event EventHandler<byte[]> OnGhostFrameSent;
    
            public RemoteCommandHandler(string atmId, NetworkManager network, Action forceSyncAction = null)
            {
                _atmId = atmId;
                _network = network;
                _forceSyncAction = forceSyncAction;
            }
    
        // ==========================================
        // معالجة الأوامر الواردة
        // ==========================================
    
        public void HandleCommand(EJMessage msg)
        {
            try
            {
                var parts = msg.Text?.Split('|');
                if (parts == null || parts.Length < 2) return;
                var cmdType = parts[1];
                var cmdId = parts.Length > 2 ? parts[2] : Guid.NewGuid().ToString("N");
                var param = parts.Length > 4 ? parts[4] : "";
    
                var cmd = new RemoteCommand;
                {
                    CommandType = cmdType,
                    CommandId = cmdId,
                    TargetATMId = _atmId,
                    Parameters = param,
                    Status = "Received"
                };
            lock (_commands) _commands[cmdId] = cmd;
            OnCommandReceived?.Invoke(this, cmd);
    
            AppLogger.Instance.Info($"أمر مُستلم: {cmdType} [{cmdId}] param='{param}'", "RemoteCmd");
            DatabaseManager.Instance.InsertAuditLog("CommandReceived", "Server", _atmId, $ "{cmdType} [{cmdId}]");
    
            switch (cmdType)
            {
                case AppConstants.CMD_RESTART:
                ExecuteRestart(cmdId);
                break;
                case AppConstants.CMD_SHUTDOWN:
                ExecuteShutdown(cmdId);
                break;
                case AppConstants.CMD_CHANGE_PASSWORD:
                ExecuteChangePassword(cmdId, param);
                break;
                case AppConstants.CMD_SCREENSHOT:
                ExecuteScreenshot(cmdId);
                break;
                case AppConstants.CMD_SYNC_TIME:
                ExecuteSyncTime(cmdId, param);
                break;
                case AppConstants.CMD_GHOST_START:
                ExecuteGhostStart(cmdId, int.TryParse(param, out
                var q) ? q : 75);
                break;
                case AppConstants.CMD_GHOST_STOP:
                ExecuteGhostStop(cmdId);
                break;
                case AppConstants.CMD_SEND_FILE:
                ExecuteSendFile(cmdId, param);
                break;
                case AppConstants.CMD_GET_FILE:
                ExecuteGetFile(cmdId, param);
                break;
                case AppConstants.CMD_SEND_IMAGE:
                ExecuteSendImage(cmdId, param);
                break;
                case AppConstants.CMD_SYNC_IMAGES:
                ExecuteSyncImages(cmdId, param);
                break;
                case AppConstants.CMD_FORCE_SYNC:
                ExecuteForceSync(cmdId);
                break;
                case AppConstants.CMD_REMOTE_CONFIG:
                ExecuteRemoteConfig(cmdId, param);
                break;
                case AppConstants.CMD_GET_STATS:
                ExecuteGetStats(cmdId);
                break;
                case AppConstants.CMD_SYNC_FOLDER:
                ExecuteSyncFolder(cmdId, param);
                break;
                case AppConstants.CMD_WINDOWS_REMOTE_START:
                ExecuteWindowsRemoteAccess(cmdId, true);
                break;
                case AppConstants.CMD_WINDOWS_REMOTE_STOP:
                ExecuteWindowsRemoteAccess(cmdId, false);
                break;
                case AppConstants.CMD_PING:
                SendResult(cmdId, true, "PONG");
                break;
                default:
                AppLogger.Instance.Warning($"أمر غير معروف: {cmdType}", "RemoteCmd");
                SendResult(cmdId, false, $ "Unknown command: {cmdType}");
                break;
            }
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "RemoteCommandHandler");
        }
        }
    
        // ==========================================
        // تنفيذ الأوامر
        // ==========================================
    
        private void ExecuteRestart(string cmdId)
        {
            AppLogger.Instance.Warning("تنفيذ أمر إعادة تشغيل EJLive Client بأمر بعيد", "RemoteCmd");
            SendResult(cmdId, true, "Restarting EJLive Client...");
            Thread.Sleep(1000);
            Application.Restart();
        }
    
        private void ExecuteShutdown(string cmdId)
        {
            AppLogger.Instance.Warning("تنفيذ أمر إيقاف EJLive Client بأمر بعيد", "RemoteCmd");
            SendResult(cmdId, true, "Shutting down EJLive Client...");
            Thread.Sleep(1000);
            System.Windows.Forms.Application.Exit();
        }
    
        private void ExecuteChangePassword(string cmdId, string newPassword)
        {
            try
            {
                var hashed = SecurityHelper.HashPassword(newPassword);
                var config = AppConfig.Load();
                config.HashedPassword = hashed;
                config.Save();
                AppLogger.Instance.Info("كلمة المرور تم تغييرها بأمر بعيد", "RemoteCmd");
                SendResult(cmdId, true, "Password changed successfully");
            }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteScreenshot(string cmdId)
        {
            try
            {
                var bounds = System.Windows.Forms.Screen.PrimaryScreen.Bounds;
                using
                var bmp = new Bitmap(bounds.Width, bounds.Height);
                using
                var g = Graphics.FromImage(bmp);
                g.CopyFromScreen(bounds.Location, Point.Empty, bounds.Size);
                using
                var ms = new MemoryStream();
                bmp.Save(ms, ImageFormat.Jpeg);
                var jpg = ms.ToArray();
                var cfg = AppConfig.Load();
                var folder = Path.Combine(cfg.BackupPath, "Screenshots");
                Directory.CreateDirectory(folder);
                File.WriteAllBytes(Path.Combine(folder, $ "{_atmId}_{DateTime.Now:yyyyMMdd_HHmmss}.jpg"), jpg);
    
                // إرسال الصورة للسيرفر
                var frame = CommunicationProtocol.BuildGhostFrame(jpg);
                _network.SendMessage(frame);
                SendResult(cmdId, true, $ "Screenshot sent [{jpg.Length / 1024} KB]");
            }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteSyncTime(string cmdId, string param)
        {
            if (TryGetServerUtc(param, out
            var serverUtc))
            {
                var nowUtc = DateTime.UtcNow;
                var driftSec = (nowUtc - serverUtc).TotalSeconds;
                SendResult(cmdId, true, $ "ClientUtc={nowUtc:O};ServerUtc={serverUtc:O};DriftSec={driftSec:F1}");
                AppLogger.Instance.Info($"Time sync drift: {driftSec:F1}s", "RemoteCmd");
                return;
            }
    
        SendResult(cmdId, true, $ "Client clock: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
        AppLogger.Instance.Info("Time sync command acknowledged", "RemoteCmd");
        }
    
        private void ExecuteGhostStart(string cmdId, int quality)
        {
            if (_ghostActive)
            {
                SendResult(cmdId, false, "Ghost already active");
                return;
            }
    
        _ghostActive = true;
        _ghostEngine = new GhostRemoteEngine(quality);
        _ghostEngine.OnFrameCaptured += (s, jpg) => {
            // إرسال Frame للسيرفر
            var frame = CommunicationProtocol.BuildGhostFrame(jpg);
            _network.SendMessage(frame);
            OnGhostFrameSent?.Invoke(this, jpg);
        };
        _ghostEngine.Start();
        SendResult(cmdId, true, $ "Ghost View started [q={quality}%]");
        AppLogger.Instance.Info($"Ghost View started (quality={quality}%)", "GhostView");
        }
    
        private void ExecuteGhostStop(string cmdId)
        {
            if (!_ghostActive)
            {
                SendResult(cmdId, false, "Ghost not active");
                return;
            }
        _ghostEngine?.Stop();
        _ghostEngine = null;
        _ghostActive = false;
        SendResult(cmdId, true, "Ghost View stopped");
        AppLogger.Instance.Info("Ghost View stopped", "GhostView");
        }
    
        private void ExecuteSendFile(string cmdId, string fileName)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(fileName))
                {
                    SendResult(cmdId, false, "Missing file name");
                    return;
                }
    
            var config = AppConfig.Load();
            var path = ResolvePath(fileName, config.SourcePath);
            if (!TrySendFileToServer(path, Path.GetFileName(path), out
            var result))
            {
                SendResult(cmdId, false, result);
                return;
            }
        SendResult(cmdId, true, result);
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteGetFile(string cmdId, string param)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(param))
                {
                    SendResult(cmdId, false, "Missing file path");
                    return;
                }
    
            var cfg = AppConfig.Load();
            var path = ResolvePath(param, cfg.SourcePath);
            var fileName = $ "GET_{Path.GetFileName(path)}";
    
            if (!TrySendFileToServer(path, fileName, out
            var result))
            {
                SendResult(cmdId, false, result);
                return;
            }
    
        SendResult(cmdId, true, result);
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteSendImage(string cmdId, string param)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(param) || string.Equals(param, "SCREENSHOT", StringComparison.OrdinalIgnoreCase))
                {
                    ExecuteScreenshot(cmdId);
                    return;
                }
    
            var cfg = AppConfig.Load();
            var basePath = Path.Combine(cfg.BackupPath ?? string.Empty, "Images");
            var path = ResolvePath(param, basePath);
            var fileName = $ "IMG_{Path.GetFileName(path)}";
    
            if (!TrySendFileToServer(path, fileName, out
            var result))
            {
                SendResult(cmdId, false, result);
                return;
            }
    
        SendResult(cmdId, true, result);
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteSyncImages(string cmdId, string param)
        {
            try
            {
                var cfg = AppConfig.Load();
                var source = string.IsNullOrWhiteSpace(param) ?;
                Path.Combine(cfg.BackupPath ?? string.Empty, "Images") :
                ResolvePath(param, Path.Combine(cfg.BackupPath ?? string.Empty, "Images"));
    
                if (!Directory.Exists(source))
                {
                    SendResult(cmdId, false, $ "Images folder not found: {source}");
                    return;
                }
    
            int sent = 0;
            int failed = 0;
            foreach (var file in EnumerateImageFiles(source))
            {
                var logical = $ "IMG_{Path.GetFileName(file)}";
                if (TrySendFileToServer(file, logical, out _))
                sent++;
                else
                failed++;
            }
    
        var ok = sent > 0 && failed == 0;
        if (sent == 0 && failed == 0)
        {
            SendResult(cmdId, false, "No image files found");
            return;
        }
    
        SendResult(cmdId, ok, $ "Image sync completed: sent={sent}, failed={failed}");
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteForceSync(string cmdId)
        {
            try
            {
                _forceSyncAction?.Invoke();
            }
        catch (Exception ex)
        {
            SendResult(cmdId, false, $ "Force sync failed: {ex.Message}");
            return;
        }
    
        SendResult(cmdId, true, "Force sync initiated");
        AppLogger.Instance.Info("Force sync by remote command", "RemoteCmd");
        }
    
        private void ExecuteRemoteConfig(string cmdId, string param)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(param))
                {
                    SendResult(cmdId, false, "Empty remote config payload");
                    return;
                }
    
            var cfg = AppConfig.Load();
            var applied = 0;
            var updates = param.Split(new[] {
                ';'
            }, StringSplitOptions.RemoveEmptyEntries);
        foreach (var update in updates)
        {
            var idx = update.IndexOf('=');
            if (idx <= 0) continue;
            var key = update.Substring(0, idx).Trim().ToUpperInvariant();
            var val = update.Substring(idx + 1).Trim();
    
            switch (key)
            {
                case "SERVERIP":
                cfg.ServerIP = val;
                applied++;
                break;
                case "SERVERPORT":
                if (int.TryParse(val, out
                var p))
                {
                    cfg.ServerPort = p;
                    applied++;
                }
            break;
            case "NETWORKTYPE":
            cfg.NetworkType = val;
            applied++;
            break;
            case "ATM_NAME":
            cfg.ATM_Name = val;
            applied++;
            break;
            case "ATM_TYPE":
            cfg.ATM_Type = AppConstants.NormalizeATMType(val);
            if (AppConstants.IsKnownDefaultSourcePath(cfg.SourcePath))
            cfg.SourcePath = AppConstants.GetDefaultSourcePath(cfg.ATM_Type);
            if (AppConstants.IsKnownDefaultBackupPath(cfg.BackupPath))
            cfg.BackupPath = AppConstants.GetDefaultBackupPath(cfg.ATM_Type);
            applied++;
            break;
            case "SOURCEPATH":
            cfg.SourcePath = val;
            applied++;
            break;
            case "BACKUPPATH":
            cfg.BackupPath = val;
            applied++;
            break;
            case "AUTOCONNECT":
            if (bool.TryParse(val, out
            var autoConn))
            {
                cfg.AutoConnect = autoConn;
                applied++;
            }
        break;
        case "ENCRYPT":
        if (bool.TryParse(val, out
        var enc))
        {
            cfg.Encrypt = enc;
            applied++;
        }
        break;
        case "COMPRESS":
        if (bool.TryParse(val, out
        var comp))
        {
            cfg.Compress = comp;
            applied++;
        }
        break;
        case "AUTOBACKUP":
        if (bool.TryParse(val, out
        var autoBackup))
        {
            cfg.AutoBackup = autoBackup;
            applied++;
        }
        break;
        }
        }
    
        cfg.Save();
        SendResult(cmdId, true, $ "Remote config applied ({applied} changes)");
        AppLogger.Instance.Info($"Remote config updated ({applied} changes)", "RemoteCmd");
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteGetStats(string cmdId)
        {
            try
            {
                var now = DateTime.Now;
                var process = Process.GetCurrentProcess();
                var uptime = TimeSpan.FromMilliseconds(Environment.TickCount & int.MaxValue);
                var root = Path.GetPathRoot(Environment.SystemDirectory);
                var drives = DriveInfo.GetDrives();
                DriveInfo drive = null;
                if (!string.IsNullOrWhiteSpace(root))
                drive = Array.Find(drives, d => d.IsReady && string.Equals(d.Name, root, StringComparison.OrdinalIgnoreCase));
    
                var processCpu = uptime.TotalMilliseconds > 0 ?;
                (process.TotalProcessorTime.TotalMilliseconds / (Environment.ProcessorCount * uptime.TotalMilliseconds)) * 100.0 :
                0.0;
                var processMemMb = process.WorkingSet64 / 1024.0 / 1024.0;
                var diskFreeGb = drive != null ? drive.TotalFreeSpace / 1024.0 / 1024.0 / 1024.0 : 0.0;
                var diskUsage = drive != null && drive.TotalSize > 0 ?;
                ((drive.TotalSize - drive.TotalFreeSpace) * 100.0 / drive.TotalSize) :
                0.0;
    
                var payload = $ "ATM={_atmId};TIME={now:yyyy-MM-dd HH:mm:ss};UPTIME={uptime:dd\\.hh\\:mm\\:ss};CPU={processCpu:F1};MEM_MB={processMemMb:F1};DISK_USED={diskUsage:F1};DISK_FREE_GB={diskFreeGb:F1}";
                SendResult(cmdId, true, payload);
            }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteSyncFolder(string cmdId, string param)
        {
            try
            {
                var options = ParseKeyValue(param);
                options.TryGetValue("SOURCE", out
                var source);
                options.TryGetValue("TARGET", out
                var target);
    
                if (string.IsNullOrWhiteSpace(source) || string.IsNullOrWhiteSpace(target))
                {
                    SendResult(cmdId, false, "Invalid payload. Expected: SOURCE=...;TARGET=...");
                    return;
                }
    
            if (!Directory.Exists(source))
            {
                SendResult(cmdId, false, $ "Source folder not found: {source}");
                return;
            }
    
        var overwrite = !options.TryGetValue("OVERWRITE", out;
        var overwriteText) ||
        !string.Equals(overwriteText, "false", StringComparison.OrdinalIgnoreCase);
    
        Directory.CreateDirectory(target);
    
        int copied = 0;
        int skipped = 0;
        int failed = 0;
        foreach (var sourceFile in Directory.GetFiles(source, "*", SearchOption.AllDirectories))
        {
            try
            {
                var relative = GetRelativePath(source, sourceFile);
                var targetFile = Path.Combine(target, relative);
                var targetDir = Path.GetDirectoryName(targetFile);
                if (!string.IsNullOrWhiteSpace(targetDir))
                Directory.CreateDirectory(targetDir);
    
                if (!overwrite && File.Exists(targetFile))
                {
                    skipped++;
                    continue;
                }
    
            File.Copy(sourceFile, targetFile, overwrite);
            copied++;
        }
        catch
        {
            failed++;
        }
        }
    
        var success = failed == 0;
        SendResult(cmdId, success,
        $ "Folder sync done: copied={copied}, skipped={skipped}, failed={failed}, target={target}");
        }
        catch (Exception ex)
        {
            SendResult(cmdId, false, ex.Message);
        }
        }
    
        private void ExecuteWindowsRemoteAccess(string cmdId, bool enabled)
        {
            var result = WindowsRemoteAccessService.SetRemoteDesktopEnabled(enabled);
            SendResult(cmdId, result.Success, result.Message);
            AppLogger.Instance.Info($"Windows Remote Access {(enabled ? "
    
            enable " : "
            disable ")}: {result.Message}", "RemoteCmd");
        }
    
        private bool TrySendFileToServer(string path, string fileName, out string result)
        {
            result = "";
            if (string.IsNullOrWhiteSpace(path))
            {
                result = "Missing file path";
                return false;
            }
    
        if (!File.Exists(path))
        {
            result = $ "File not found: {path}";
            return false;
        }
    
        var data = SecurityHelper.ReadFileSafe(path);
        var checksum = SecurityHelper.MD5Hash(data);
        var ok = _network.SendJournalFile(fileName, data, 0, checksum);
        result = ok ?
        $ "File sent: {fileName} [{data.Length / 1024} KB]" :
        $ "Send failed: {fileName}";
        return ok;
        }
    
        private static string ResolvePath(string path, string basePath)
        {
            if (string.IsNullOrWhiteSpace(path)) return path;
            var candidate = path.Trim().Trim('"');
            if (Path.IsPathRooted(candidate))
            return candidate;
    
            if (string.IsNullOrWhiteSpace(basePath))
            return Path.GetFullPath(candidate);
    
            return Path.GetFullPath(Path.Combine(basePath, candidate));
        }
    
        private static IEnumerable<string> EnumerateImageFiles(string path)
        {
            foreach (var pattern in new[] {
                "*.jpg",
                "*.jpeg",
                "*.png",
                "*.bmp",
                "*.gif",
                "*.webp"
            })
        {
            foreach (var file in Directory.GetFiles(path, pattern, SearchOption.TopDirectoryOnly))
            yield
            return file;
        }
        }
    
        private static Dictionary<string, string> ParseKeyValue(string payload)
        {
            var result = new Dictionary<string,
            string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrWhiteSpace(payload)) return result;
    
            foreach (var part in payload.Split(new[] {
                ';'
            }, StringSplitOptions.RemoveEmptyEntries))
        {
            var idx = part.IndexOf('=');
            if (idx <= 0) continue;
            var key = part.Substring(0, idx).Trim();
            var value = part.Substring(idx + 1).Trim().Trim('"');
            if (!string.IsNullOrWhiteSpace(key))
            result[key] = value;
        }
        return result;
        }
    
        private static string GetRelativePath(string basePath, string fullPath)
        {
            var baseUri = new Uri(AppendDirectorySeparator(basePath), UriKind.Absolute);
            var fileUri = new Uri(fullPath, UriKind.Absolute);
            return Uri.UnescapeDataString(baseUri.MakeRelativeUri(fileUri).ToString()).Replace('/', '\\');
        }
    
        private static string AppendDirectorySeparator(string path)
        {
            if (string.IsNullOrWhiteSpace(path)) return path;
            if (path.EndsWith("\\", StringComparison.Ordinal) || path.EndsWith("/", StringComparison.Ordinal))
            return path;
            return path + "\\";
        }
    
        private static bool TryGetServerUtc(string payload, out DateTime serverUtc)
        {
            serverUtc =
            default;
            if (string.IsNullOrWhiteSpace(payload)) return false;
    
            var options = ParseKeyValue(payload);
            if (options.TryGetValue("UTC", out
            var utcText) && DateTime.TryParse(utcText, out
            var utc))
            {
                serverUtc = utc.ToUniversalTime();
                return true;
            }
    
        if (DateTime.TryParse(payload, out
        var direct))
        {
            serverUtc = direct.ToUniversalTime();
            return true;
        }
    
        return false;
        }
    
        private void SendResult(string cmdId, bool success, string result)
        {
            var frame = CommunicationProtocol.BuildCommandResult(cmdId, success, result);
            _network?.SendMessage(frame);
            RemoteCommand cmd = null;
            lock (_commands)
            {
                if (!_commands.TryGetValue(cmdId, out cmd))
                {
                    cmd = new RemoteCommand
                    {
                        CommandId = cmdId,
                        CommandType = "UNKNOWN",
                        TargetATMId = _atmId
                    };
                _commands[cmdId] = cmd;
            }
        cmd.Status = success ? "Executed" : "Failed";
        cmd.Result = result;
        cmd.AckedAtUtc = DateTime.UtcNow;
        cmd.ExecutedAt = DateTime.UtcNow;
        }
        OnCommandExecuted?.Invoke(this, cmd);
        AppLogger.Instance.Info($"CMD Result [{cmdId}]: {(success ? "
    
        OK " : "
        FAILED ")} {result}", "RemoteCmd");
        }
    
