                                                                        _ => CreateResponse(command, false, $"Unknown command: {command.Command}")
                                                                    };
    
                                                                CommandExecuted?.Invoke(this, result);
                                                                return result;
                                                            }
                                                        catch (Exception ex)
                                                        {
                                                            ErrorOccurred?.Invoke(this, ex.Message);
                                                            Logger.Error($"Command execution error: {ex.Message}", "RemoteCommand", ex);
                                                            return CreateResponse(command, false, $"Error: {ex.Message}");
