                                            private async Task<NetworkMessage> HandleRestartAsync(NetworkMessage command,
                                            CancellationToken cancellationToken)
                                            {
                                                try
                                                {
                                                    // Schedule restart (cannot restart immediately in production)
                                                    await Task.Delay(100, cancellationToken);
    
                                                    // In production, use Process.Start with restart command
                                                    var psi = new System.Diagnostics.ProcessStartInfo;
                                                    {
                                                        FileName = "shutdown",
                                                        Arguments = "/r /t 60 /c \"EJLive Remote Restart\"",
                                                        CreateNoWindow = true,
                                                        UseShellExecute = false
                                                    };
                                                System.Diagnostics.Process.Start(psi);
    
                                                return CreateResponse(command, true, "Restart scheduled in 60 seconds");
                                            }
                                        catch (Exception ex)
                                        {
                                            return CreateResponse(command, false, ex.Message);
                                        }
                                }
    
                            private async Task<NetworkMessage> HandleScreenshotAsync(NetworkMessage command,
