                                {
                                    var payload = System.Text.Json.JsonSerializer.Deserialize<ScreenshotPayload>(command.Payload);
                                    ?? new ScreenshotPayload();
    
                                    var screenshot = CaptureScreen(payload.Width, payload.Height);
                                    var ms = new MemoryStream();
                                    screenshot.Save(ms, ImageFormat.Png);
                                    var imageBytes = ms.ToArray();
    
                                    var compressed = SecurityHelper.Compress(imageBytes);
    
                                    var response = CreateResponse(command, true, $"Screenshot captured: {imageBytes.Length} bytes");
                                    response.BinaryData = compressed;
                                    response.Payload = System.Text.Json.JsonSerializer.Serialize(new { width = screenshot.Width, height = screenshot.Height });
    
                                    ScreenshotCaptured?.Invoke(this, $"Screenshot captured: {imageBytes.Length} bytes");
                                    return response;
                                }
                            catch (Exception ex)
                            {
                                return CreateResponse(command, false, ex.Message);
                            }
                    }
    
                private async Task<NetworkMessage> HandleTimeSyncAsync(NetworkMessage command,
                CancellationToken cancellationToken)
                {
                    try
                    {
                        var serverPayload = System.Text.Json.JsonSerializer.Deserialize<TimeSyncPayload>(command.Payload);
                        ?? new TimeSyncPayload();
    
                        // Set system time (requires admin privileges)
                        var localTime = DateTimeHelper.ToLocalTime(serverPayload.ServerTime, serverPayload.Timezone);
    
                        // Use Win32 API or PowerShell to set time
                        var psi = new System.Diagnostics.ProcessStartInfo;
                        {
                            FileName = "powershell",
                            Arguments = $"-Command \"Set-Date -Date '{localTime:yyyy-MM-dd HH:mm:ss}'\"",
                            CreateNoWindow = true,
                            UseShellExecute = false,
                            Verb = "runas"
                        };
    
                    using var process = System.Diagnostics.Process.Start(psi);
                    if (process != null)
                    await process.WaitForExitAsync(cancellationToken);
    
                    return CreateResponse(command, true, $"Time synchronized to {localTime:yyyy-MM-dd HH:mm:ss}");
                }
            catch (Exception ex)
            {
                return CreateResponse(command, false, ex.Message);
            }
        }
    
        private async Task<NetworkMessage> HandlePasswordChangeAsync(NetworkMessage command,
        CancellationToken cancellationToken)
        {
            try
            {
                var newPassword = SecurityHelper.GenerateSecurePassword(16);
    
                // In production, update the ATM software configuration
                // For NCR: Update registry or config file
                // For GRG: Update INI file
                // For WN: Update ProTopas config
    
                await Task.Delay(100, cancellationToken);
    
                return CreateResponse(command, true, "Password changed successfully",
                System.Text.Json.JsonSerializer.Serialize(new { password = newPassword }));
            }
        catch (Exception ex)
        {
            return CreateResponse(command, false, ex.Message);
        }
        }
    
        private async Task<NetworkMessage> HandleGhostRemoteAsync(NetworkMessage command,
        CancellationToken cancellationToken)
        {
            try
            {
                // Ghost Remote - access ATM without affecting operations
                // 1. Do not log out current user
                // 2. Do not lock screen
                // 3. Start remote viewing session
    
                var ghostSession = new;
                {
                    sessionId = Guid.NewGuid().ToString(),
                    operatorName = command.Payload,
                    startTime = DateTime.UtcNow,
                    mode = "ghost"
                };
    
            Logger.Info($"Ghost remote started by {command.Payload}", "RemoteCommand");
    
            return CreateResponse(command, true, "Ghost remote session started",
            System.Text.Json.JsonSerializer.Serialize(ghostSession));
        }
        catch (Exception ex)
        {
            return CreateResponse(command, false, ex.Message);
        }
        }
    
        private async Task<NetworkMessage> HandleGetLogAsync(NetworkMessage command,
        CancellationToken cancellationToken)
        {
            try
            {
                var logPath = @"C:\EJLive_Storage\Logs";
                var logFiles = Directory.GetFiles(logPath, "*.log");
                .OrderByDescending(f => File.GetLastWriteTime(f))
                .Take(5)
                .ToList();
    
                var logContents = new List<string>();
                foreach (var logFile in logFiles)
                {
                    var content = await File.ReadAllTextAsync(logFile, cancellationToken);
                    logContents.Add($"=== {Path.GetFileName(logFile)} ===\n{content}");
                }
    
            var combined = string.Join("\n\n", logContents);
            var compressed = SecurityHelper.CompressString(combined);
    
            return CreateResponse(command, true, $"Retrieved {logFiles.Count} log files",
            compressed);
        }
        catch (Exception ex)
        {
            return CreateResponse(command, false, ex.Message);
        }
        }
    
        private async Task<NetworkMessage> HandleUpdateConfigAsync(NetworkMessage command,
        CancellationToken cancellationToken)
        {
            try
            {
                var config = System.Text.Json.JsonSerializer.Deserialize<ATMConfig>(command.Payload);
                if (config == null)
                return CreateResponse(command, false, "Invalid configuration data");
    
                // Save configuration to file
                var configPath = @"C:\EJLive_Storage\config.json";
                var json = System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions;
                {
                    WriteIndented = true
                });
            await File.WriteAllTextAsync(configPath, json, cancellationToken);
    
            return CreateResponse(command, true, "Configuration updated successfully");
        }
        catch (Exception ex)
        {
            return CreateResponse(command, false, ex.Message);
        }
        }
    
        private async Task<NetworkMessage> HandlePingAsync(NetworkMessage command,
        CancellationToken cancellationToken)
        {
            await Task.Delay(1, cancellationToken);
            return CreateResponse(command, true, "PONG", System.Text.Json.JsonSerializer.Serialize(new
            {
                timestamp = DateTime.UtcNow,
                uptime = Environment.TickCount64
            }));
        }
    
        private NetworkMessage CreateResponse(NetworkMessage original, bool success, string message, string? payload = null)
        {
            return new NetworkMessage
            {
                MessageId = Guid.NewGuid(),
                Command = success ? CommandType.ACK : CommandType.NAK,
                DeviceId = original.DeviceId,
                Timestamp = DateTime.UtcNow,
                Payload = payload ?? System.Text.Json.JsonSerializer.Serialize(new { success, message })
            };
        }
    
        private Bitmap CaptureScreen(int maxWidth = 1024, int maxHeight = 768)
        {
            var screenBounds = Screen.PrimaryScreen!.Bounds;
            var width = Math.Min(screenBounds.Width, maxWidth);
            var height = Math.Min(screenBounds.Height, maxHeight);
    
            var bitmap = new Bitmap(width, height);
            using (var g = Graphics.FromImage(bitmap))
            {
                g.CopyFromScreen(0, 0, 0, 0, new Size(width, height), CopyPixelOperation.SourceCopy);
            }
        return bitmap;
        }
        }
