        private readonly Dictionary<string, RemoteCommand> _commands =
        new Dictionary<string, RemoteCommand>(StringComparer.OrdinalIgnoreCase);
    
        public void HandleCommand(EJMessage msg)
        {
            try
            {
                var parts   = msg.Text?.Split('|');
                if (parts == null || parts.Length < 2) return;
                var cmdType = parts[1];
                var cmdId   = parts.Length > 2 ? parts[2] : Guid.NewGuid().ToString("N");
                var param   = parts.Length > 4 ? parts[4] : "";
    
                var cmd = new RemoteCommand { CommandType = cmdType, CommandId = cmdId, TargetATMId = _atmId, Parameters = param, Status = "Received" };
            lock (_commands) _commands[cmdId] = cmd;
            OnCommandReceived?.Invoke(this, cmd);
    
            AppLogger.Instance.Info($"أمر مُستلم: {cmdType} [{cmdId}] param='{param}'", "RemoteCmd");
            DatabaseManager.Instance.InsertAuditLog("CommandReceived", "Server", _atmId, $"{cmdType} [{cmdId}]");
    
            switch (cmdType)
            {
                case AppConstants.CMD_RESTART:         ExecuteRestart(cmdId);      break;
                case AppConstants.CMD_SHUTDOWN:        ExecuteShutdown(cmdId);     break;
                case AppConstants.CMD_CHANGE_PASSWORD: ExecuteChangePassword(cmdId, param); break;
                case AppConstants.CMD_SCREENSHOT:      ExecuteScreenshot(cmdId);   break;
                case AppConstants.CMD_SYNC_TIME:       ExecuteSyncTime(cmdId, param); break;
                case AppConstants.CMD_GHOST_START:     ExecuteGhostStart(cmdId, int.TryParse(param, out var q) ? q : 75); break;
                case AppConstants.CMD_GHOST_STOP:      ExecuteGhostStop(cmdId);    break;
                case AppConstants.CMD_SEND_FILE:       ExecuteSendFile(cmdId, param); break;
                case AppConstants.CMD_GET_FILE:        ExecuteGetFile(cmdId, param); break;
                case AppConstants.CMD_SEND_IMAGE:      ExecuteSendImage(cmdId, param); break;
                case AppConstants.CMD_SYNC_IMAGES:     ExecuteSyncImages(cmdId, param); break;
                case AppConstants.CMD_FORCE_SYNC:      ExecuteForceSync(cmdId);    break;
                case AppConstants.CMD_REMOTE_CONFIG:   ExecuteRemoteConfig(cmdId, param); break;
                case AppConstants.CMD_GET_STATS:       ExecuteGetStats(cmdId);     break;
                case AppConstants.CMD_SYNC_FOLDER:     ExecuteSyncFolder(cmdId, param); break;
                case AppConstants.CMD_WINDOWS_REMOTE_START: ExecuteWindowsRemoteAccess(cmdId, true); break;
                case AppConstants.CMD_WINDOWS_REMOTE_STOP:  ExecuteWindowsRemoteAccess(cmdId, false); break;
                case AppConstants.CMD_PING:            SendResult(cmdId, true, "PONG"); break;
                default:
                AppLogger.Instance.Warning($"أمر غير معروف: {cmdType}", "RemoteCmd");
                SendResult(cmdId, false, $"Unknown command: {cmdType}");
                break;
            }
        }
        catch (Exception ex)
        {
            AppLogger.Instance.Error(ex, "RemoteCommandHandler");
        }
        }
    
