                public void ExecuteCommand(string command, string payload)
                {
                    switch (command.ToUpper())
                    {
                        case "RESTART":
                            RestartSystem();
                            break;
                        case "SCREENSHOT":
                            CaptureScreen();
                            break;
                        case "SYNC_TIME":
                            SyncTime(payload);
                            break;
                        case "CHANGE_PWD":
                            ChangePassword(payload);
                            break;
                    }
                }
                private void RestartSystem()
                {
                    Process.Start("shutdown", "/r /t 0");
                }
                private void CaptureScreen()
                {
                    Rectangle bounds = Screen.PrimaryScreen.Bounds;
                    using (Bitmap bitmap = new Bitmap(bounds.Width, bounds.Height))
                    {
                        using (Graphics g = Graphics.FromImage(bitmap))
                        {
                            g.CopyFromScreen(Point.Empty, Point.Empty, bounds.Size);
                        }
                        string path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "Screenshots");
                        if (!Directory.Exists(path)) Directory.CreateDirectory(path);
                        string fileName = $"Screen_{DateTime.Now:yyyyMMdd_HHmmss}.png";
                        bitmap.Save(Path.Combine(path, fileName), ImageFormat.Png);
                        // Logic to send this file back to server would be called here
                    }
                }
                private void SyncTime(string dateTimeStr)
                {
                    if (DateTime.TryParse(dateTimeStr, out DateTime newTime))
                    {
                        SystemTime st = new SystemTime
                        {
                            Year = (short)newTime.Year,
                            Month = (short)newTime.Month,
                            Day = (short)newTime.Day,
                            Hour = (short)newTime.Hour,
                            Minute = (short)newTime.Minute,
                            Second = (short)newTime.Second
                        };
                        SetSystemTime(ref st);
                    }
                }
