            /// <summary>
            /// معالج الأوامر البعيدة المتقدم
            /// </summary>
            public class AdvancedRemoteCommandHandler
            {
                private string _atmId;
                private string _screenshotPath;
    
                public event Action<string> OnLogMessage;
                public event Action<RemoteCommand> OnCommandExecuted;
    
                /// <summary>
                /// منشئ الفئة
                /// </summary>
                public AdvancedRemoteCommandHandler(string atmId)
                {
                _atmId = atmId;
                _screenshotPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "screenshots");
    
                // إنشاء مجلد لحفظ اللقطات
                if (!Directory.Exists(_screenshotPath))
                    Directory.CreateDirectory(_screenshotPath);
                }
    
                /// <summary>
                /// تنفيذ أمر بعيد
                /// </summary>
                public RemoteCommand ExecuteCommand(RemoteCommand command)
                {
                try
                {
                    LogMessage($"جاري تنفيذ الأمر: {command.GetCommandDescription()}");
    
                    switch (command.CommandType)
                    {
                    case RemoteCommandType.Restart:
                        ExecuteRestart(command);
                        break;
    
                    case RemoteCommandType.Screenshot:
                        ExecuteScreenshot(command);
                        break;
    
                    case RemoteCommandType.SyncTime:
                        ExecuteSyncTime(command);
                        break;
    
                    case RemoteCommandType.StartSync:
                        ExecuteStartSync(command);
                        break;
    
                    case RemoteCommandType.StopSync:
                        ExecuteStopSync(command);
                        break;
    
                    case RemoteCommandType.GetStatus:
                        ExecuteGetStatus(command);
                        break;
    
                    case RemoteCommandType.Reboot:
                        ExecuteReboot(command);
                        break;
    
                    case RemoteCommandType.Shutdown:
                        ExecuteShutdown(command);
                        break;
    
                    default:
                        command.Status = "Failed";
                        command.Result = "أمر غير معروف";
                        break;
                    }
    
                    command.ExecutedAt = DateTime.Now;
                    OnCommandExecuted?.Invoke(command);
                    return command;
                }
                catch (Exception ex)
                {
                    LogMessage($"خطأ في تنفيذ الأمر: {ex.Message}");
                    command.Status = "Error";
                    command.Result = ex.Message;
                    return command;
                }
                }
    
                /// <summary>
                /// تنفيذ أمر إعادة التشغيل
                /// </summary>
                private void ExecuteRestart(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري إعادة تشغيل التطبيق...");
                    command.Status = "Executing";
                    command.Result = "تم بدء إعادة التشغيل";
    
                    // إعادة تشغيل التطبيق
                    Application.Restart();
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشل إعادة التشغيل: {ex.Message}";
                }
                }
    
                /// <summary>
                /// التقاط لقطة شاشة
                /// </summary>
                private void ExecuteScreenshot(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري التقاط لقطة الشاشة...");
    
                    // التقاط الشاشة
                    Bitmap screenshot = new Bitmap(Screen.PrimaryScreen.Bounds.Width, Screen.PrimaryScreen.Bounds.Height);
                    Graphics graphics = Graphics.FromImage(screenshot);
                    graphics.CopyFromScreen(0, 0, 0, 0, Screen.PrimaryScreen.Bounds.Size);
    
                    // حفظ اللقطة
                    string fileName = $"screenshot_{DateTime.Now:yyyyMMdd_HHmmss}.png";
                    string filePath = Path.Combine(_screenshotPath, fileName);
                    screenshot.Save(filePath);
    
                    command.Status = "Completed";
                    command.Result = filePath;
                    command.Parameters["FileName"] = fileName;
    
                    LogMessage($"تم حفظ اللقطة: {filePath}");
    
                    graphics.Dispose();
                    screenshot.Dispose();
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشل التقاط اللقطة: {ex.Message}";
                }
                }
    
                /// <summary>
                /// مزامنة الوقت
                /// </summary>
                private void ExecuteSyncTime(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري مزامنة الوقت...");
    
                    // الحصول على الوقت الحالي
                    DateTime currentTime = DateTime.Now;
                    command.Status = "Completed";
                    command.Result = currentTime.ToString("yyyy-MM-dd HH:mm:ss");
                    command.Parameters["CurrentTime"] = currentTime.ToString("O");
    
                    LogMessage($"تم مزامنة الوقت: {currentTime:yyyy-MM-dd HH:mm:ss}");
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشلت مزامنة الوقت: {ex.Message}";
                }
                }
    
                /// <summary>
                /// بدء المزامنة
                /// </summary>
                private void ExecuteStartSync(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري بدء المزامنة...");
                    command.Status = "Executing";
                    command.Result = "تم بدء المزامنة";
    
                    // يمكن إضافة منطق بدء المزامنة هنا
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشل بدء المزامنة: {ex.Message}";
                }
                }
    
                /// <summary>
                /// إيقاف المزامنة
                /// </summary>
                private void ExecuteStopSync(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري إيقاف المزامنة...");
                    command.Status = "Executing";
                    command.Result = "تم إيقاف المزامنة";
    
                    // يمكن إضافة منطق إيقاف المزامنة هنا
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشل إيقاف المزامنة: {ex.Message}";
                }
                }
    
                /// <summary>
                /// الحصول على حالة النظام
                /// </summary>
                private void ExecuteGetStatus(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري الحصول على حالة النظام...");
    
                    // جمع معلومات النظام
                    StringBuilder statusInfo = new StringBuilder();
                    statusInfo.AppendLine($"معرف الصراف: {_atmId}");
                    statusInfo.AppendLine($"الوقت الحالي: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
                    statusInfo.AppendLine($"إصدار البرنامج: {AppConstants.AppVersion}");
                    statusInfo.AppendLine($"حالة الذاكرة: {GC.GetTotalMemory(false) / 1024 / 1024} MB");
    
                    command.Status = "Completed";
                    command.Result = statusInfo.ToString();
    
                    LogMessage("تم جمع معلومات الحالة");
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشل الحصول على الحالة: {ex.Message}";
                }
                }
    
                /// <summary>
                /// إعادة تشغيل النظام
                /// </summary>
                private void ExecuteReboot(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري إعادة تشغيل النظام...");
                    command.Status = "Executing";
                    command.Result = "تم بدء إعادة تشغيل النظام";
    
                    // تنفيذ أمر إعادة التشغيل
                    ProcessStartInfo psi = new ProcessStartInfo("shutdown", "/r /t 30 /c \"إعادة تشغيل بأمر بعيد\"");
                    psi.UseShellExecute = false;
                    Process.Start(psi);
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشلت إعادة التشغيل: {ex.Message}";
                }
                }
    
                /// <summary>
                /// إيقاف النظام
                /// </summary>
                private void ExecuteShutdown(RemoteCommand command)
                {
                try
                {
                    LogMessage("جاري إيقاف النظام...");
                    command.Status = "Executing";
                    command.Result = "تم بدء إيقاف النظام";
    
                    // تنفيذ أمر الإيقاف
                    ProcessStartInfo psi = new ProcessStartInfo("shutdown", "/s /t 30 /c \"إيقاف بأمر بعيد\"");
                    psi.UseShellExecute = false;
                    Process.Start(psi);
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"فشل إيقاف النظام: {ex.Message}";
                }
                }
    
                /// <summary>
                /// تسجيل الرسالة
                /// </summary>
                private void LogMessage(string message)
                {
                OnLogMessage?.Invoke($"[{DateTime.Now:HH:mm:ss}] {message}");
                }
            }
