            /// <summary>
            /// Advanced remote command handler for client-side command execution.
            /// </summary>
            public class AdvancedRemoteCommandHandler
            {
                private readonly string _atmId;
                private readonly string _screenshotPath;
    
                public event Action<string>? OnLogMessage;
                public event Action<RemoteCommand>? OnCommandExecuted;
    
                public AdvancedRemoteCommandHandler(string atmId)
                {
                _atmId = atmId;
                _screenshotPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "screenshots");
                Directory.CreateDirectory(_screenshotPath);
                }
    
                public RemoteCommand ExecuteCommand(RemoteCommand command)
                {
                try
                {
                    switch (command.CommandType)
                    {
                    case RemoteCommandType.Restart:     ExecuteRestart(command); break;
                    case RemoteCommandType.Screenshot:  ExecuteScreenshot(command); break;
                    case RemoteCommandType.SyncTime:    ExecuteSyncTime(command); break;
                    case RemoteCommandType.StartSync:   ExecuteStartSync(command); break;
                    case RemoteCommandType.StopSync:    ExecuteStopSync(command); break;
                    case RemoteCommandType.GetStatus:   ExecuteGetStatus(command); break;
                    case RemoteCommandType.Reboot:      ExecuteReboot(command); break;
                    case RemoteCommandType.Shutdown:    ExecuteShutdown(command); break;
                    default:
                        command.Status = "Failed";
                        command.Result = "Unknown command";
                        break;
                    }
    
                    command.ExecutedAt = DateTime.Now;
                    OnCommandExecuted?.Invoke(command);
                    return command;
                }
                catch (Exception ex)
                {
                    LogMessage($"Command error: {ex.Message}");
                    command.Status = "Error";
                    command.Result = ex.Message;
                    return command;
                }
                }
    
                private void ExecuteRestart(RemoteCommand command)
                {
                try
                {
                    LogMessage("Restarting application...");
                    command.Status = "Executing";
                    command.Result = "Restart initiated";
                    Application.Restart();
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Restart failed: {ex.Message}";
                }
                }
    
                private void ExecuteScreenshot(RemoteCommand command)
                {
                try
                {
                    using var screenshot = new Bitmap(Screen.PrimaryScreen.Bounds.Width, Screen.PrimaryScreen.Bounds.Height);
                    using var graphics = Graphics.FromImage(screenshot);
                    graphics.CopyFromScreen(0, 0, 0, 0, Screen.PrimaryScreen.Bounds.Size);
    
                    var fileName = $"screenshot_{DateTime.Now:yyyyMMdd_HHmmss}.png";
                    var filePath = Path.Combine(_screenshotPath, fileName);
                    screenshot.Save(filePath);
    
                    command.Status = "Completed";
                    command.Result = filePath;
                    command.Parameters["FileName"] = fileName;
                    LogMessage($"Screenshot saved: {filePath}");
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Screenshot failed: {ex.Message}";
                }
                }
    
                private void ExecuteSyncTime(RemoteCommand command)
                {
                try
                {
                    var now = DateTime.Now;
                    command.Status = "Completed";
                    command.Result = now.ToString("yyyy-MM-dd HH:mm:ss");
                    command.Parameters["CurrentTime"] = now.ToString("O");
                    LogMessage($"Time synced: {now:yyyy-MM-dd HH:mm:ss}");
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Time sync failed: {ex.Message}";
                }
                }
    
                private void ExecuteStartSync(RemoteCommand command)
                {
                try
                {
                    LogMessage("Starting sync...");
                    command.Status = "Executing";
                    command.Result = "Sync started";
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Start sync failed: {ex.Message}";
                }
                }
    
                private void ExecuteStopSync(RemoteCommand command)
                {
                try
                {
                    LogMessage("Stopping sync...");
                    command.Status = "Executing";
                    command.Result = "Sync stopped";
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Stop sync failed: {ex.Message}";
                }
                }
    
                private void ExecuteGetStatus(RemoteCommand command)
                {
                try
                {
                    var sb = new StringBuilder();
                    sb.AppendLine($"ATM ID: {_atmId}");
                    sb.AppendLine($"Time: {DateTime.Now:yyyy-MM-dd HH:mm:ss}");
                    sb.AppendLine($"Version: {AppConstants.AppVersion}");
                    sb.AppendLine($"Memory: {GC.GetTotalMemory(false) / 1024 / 1024} MB");
    
                    command.Status = "Completed";
                    command.Result = sb.ToString();
                    LogMessage("Status collected");
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Get status failed: {ex.Message}";
                }
                }
    
                private static void ExecuteReboot(RemoteCommand command)
                {
                try
                {
                    command.Status = "Executing";
                    command.Result = "System reboot initiated";
                    var psi = new ProcessStartInfo("shutdown", "/r /t 30 /c \"Remote reboot\"") { UseShellExecute = false };
                    Process.Start(psi);
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Reboot failed: {ex.Message}";
                }
                }
    
                private static void ExecuteShutdown(RemoteCommand command)
                {
                try
                {
                    command.Status = "Executing";
                    command.Result = "System shutdown initiated";
                    var psi = new ProcessStartInfo("shutdown", "/s /t 30 /c \"Remote shutdown\"") { UseShellExecute = false };
                    Process.Start(psi);
                }
                catch (Exception ex)
                {
                    command.Status = "Failed";
                    command.Result = $"Shutdown failed: {ex.Message}";
                }
                }
    
                private void LogMessage(string message)
                {
                OnLogMessage?.Invoke($"[{DateTime.Now:HH:mm:ss}] {message}");
                }
            }
