            // Variant: d:\EJLIVE\EJlive_Reference_Projects\EJLive_38\src\EJLive.Client.WinForms\Services\AdvancedRemoteCommandHandler.cs
            public RemoteCommand ExecuteCommand(RemoteCommand command)
            {
            try
            {
                switch (command.CommandType)
                {
                case RemoteCommandType.Restart:     ExecuteRestart(command); break;
                case RemoteCommandType.Screenshot:  ExecuteScreenshot(command); break;
                case RemoteCommandType.SyncTime:    ExecuteSyncTime(command); break;
                case RemoteCommandType.StartSync:   ExecuteStartSync(command); break;
                case RemoteCommandType.StopSync:    ExecuteStopSync(command); break;
                case RemoteCommandType.GetStatus:   ExecuteGetStatus(command); break;
                case RemoteCommandType.Reboot:      ExecuteReboot(command); break;
                case RemoteCommandType.Shutdown:    ExecuteShutdown(command); break;
                default:
                    command.Status = "Failed";
                    command.Result = "Unknown command";
                    break;
                }
    
                command.ExecutedAt = DateTime.Now;
                OnCommandExecuted?.Invoke(command);
                return command;
            }
            catch (Exception ex)
            {
                LogMessage($"Command error: {ex.Message}");
                command.Status = "Error";
                command.Result = ex.Message;
                return command;
            }
            }
    
    
