            }
            catch (Exception ex)
            {
                LogMessage($"خطأ في تنفيذ الأمر: {ex.Message}");
                command.Status = "Error";
                command.Result = ex.Message;
                return command;
            }
            }
    
            /// <summary>
            /// تنفيذ أمر إعادة التشغيل
            /// </summary>
            private void ExecuteRestart(RemoteCommand command)
            {
            try
            {
                LogMessage("جاري إعادة تشغيل التطبيق...");
                command.Status = "Executing";
                command.Result = "تم بدء إعادة التشغيل";
    
                // إعادة تشغيل التطبيق
                Application.Restart();
            }
            catch (Exception ex)
            {
                command.Status = "Failed";
                command.Result = $ "فشل إعادة التشغيل: {ex.Message}";
            }
            }
    
            /// <summary>
            /// التقاط لقطة شاشة
            /// </summary>
            private void ExecuteScreenshot(RemoteCommand command)
            {
            try
            {
                LogMessage("جاري التقاط لقطة الشاشة...");
    
                // التقاط الشاشة
                Bitmap screenshot = new Bitmap(Screen.PrimaryScreen.Bounds.Width, Screen.PrimaryScreen.Bounds.Height);
                Graphics graphics = Graphics.FromImage(screenshot);
                graphics.CopyFromScreen(0, 0, 0, 0, Screen.PrimaryScreen.Bounds.Size);
    
                // حفظ اللقطة
                string fileName = $ "screenshot_{DateTime.Now:yyyyMMdd_HHmmss}.png";
                string filePath = Path.Combine(_screenshotPath, fileName);
                screenshot.Save(filePath);
    
                command.Status = "Completed";
                command.Result = filePath;
                command.Parameters["FileName"] = fileName;
    
                LogMessage($"تم حفظ اللقطة: {filePath}");
    
                graphics.Dispose();
                screenshot.Dispose();
            }
            catch (Exception ex)
            {
                command.Status = "Failed";
                command.Result = $ "فشل التقاط اللقطة: {ex.Message}";
            }
            }
    
            /// <summary>
            /// مزامنة الوقت
            /// </summary>
            private void ExecuteSyncTime(RemoteCommand command)
            {
            try
            {
                LogMessage("جاري مزامنة الوقت...");
    
                // الحصول على الوقت الحالي
                DateTime currentTime = DateTime.Now;
                command.Status = "Completed";
                command.Result = currentTime.ToString("yyyy-MM-dd HH:mm:ss");
                command.Parameters["CurrentTime"] = currentTime.ToString("O");
    
                LogMessage($"تم مزامنة الوقت: {currentTime:yyyy-MM-dd HH:mm:ss}");
            }
            catch (Exception ex)
            {
                command.Status = "Failed";
                command.Result = $ "فشلت مزامنة الوقت: {ex.Message}";
            }
            }
    
